    "year_founded": "1973",
    "tax_id": "51-0178807",
    "contact_first_name": "Diane",
    "contact_last_name": "Pascal",
    "contact_title": "Chief Development Officer",
    "contact_email": "dpascal@centeronhalsted.org",
