    "year_founded": "1985",
    "tax_id": "45-0467524",
    "contact_first_name": "Rebekah",
    "contact_last_name": "Scheinfeld",
    "contact_title": "CEO",
    "contact_email": "rscheinfeld@ccachicago.org",
    "leader_first_name": "Karrie",
    "leader_last_name": "Miner",
